css:
.blueprint {
  position: fixed; inset: 0; pointer-events: none; z-index: 1;
  max-width: 1400px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(4, 1fr);
}
.blueprint > div { border-right: 1px solid rgba(255,255,255,0.05); height: 100%; }
.blueprint > div:last-child { border-right: none; }
@media (max-width: 700px) {
  .blueprint { display: none; }
}

.wrap { max-width: 1360px; margin: 0 auto; }
section { padding: 90px 40px; position: relative; z-index: 2; }
.demo-heading { font-weight: 600; font-size: clamp(26px, 3.5vw, 40px); letter-spacing: -0.03em; margin-bottom: 16px; }
.demo-texto { color: var(--text-muted); line-height: 1.6; max-width: 520px; margin: 0; }
